cypress_script:
describe('Contact Form Submission', () => {
  it('should successfully submit the contact form', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('input[name="email"]').type('john.doe@example.com');
    cy.get('input[name="subject"]').type('Feedback');
    cy.get('textarea#message').type('This is a test feedback message.');
    cy.get('input[name="submit"]').click();
    cy.url().should('include', '/success');
  });

  it('should not submit the form when the email is invalid', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('input[name="email"]').type('invalid-email');
    cy.get('input[name="subject"]').type('Feedback');
    cy.get('textarea#message').type('This is a test feedback message.');
    cy.get('input[name="submit"]').click();
    cy.url().should('include', '/contact_us');
  });
});

playwright_script:
test.describe('Contact Form Submission', () => {
  test('should successfully submit the contact form', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.fill('input[name="name"]', 'John Doe');
    await page.fill('input[name="email"]', 'john.doe@example.com');
    await page.fill('input[name="subject"]', 'Feedback');
    await page.fill('textarea#message', 'This is a test feedback message.');
    await page.click('input[name="submit"]');
    await page.waitForURL('**/success');
  });

  test('should not submit the form when the email is invalid', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.fill('input[name="name"]', 'John Doe');
    await page.fill('input[name="email"]', 'invalid-email');
    await page.fill('input[name="subject"]', 'Feedback');
    await page.fill('textarea#message', 'This is a test feedback message.');
    await page.click('input[name="submit"]');
    await page.waitForURL('https://automationexercise.com/contact_us');
  });
});
